SELECT COUNT(CASE WHEN b.behavior_type = 6 AND b.source = 4 THEN 1 END) AS impressions, COUNT(CASE WHEN b.behavior_type = 1 AND b.source = 4 THEN 1 END) AS clicks, COUNT(CASE WHEN b.behavior_type = 1 THEN 1 END) AS total_views, CASE WHEN COUNT(CASE WHEN b.behavior_type = 6 AND b.source = 4 THEN 1 END) = 0 THEN 0 ELSE ROUND(100 * COUNT(CASE WHEN b.behavior_type = 1 AND b.source = 4 THEN 1 END) / COUNT(CASE WHEN b.behavior_type = 6 AND b.source = 4 THEN 1 END), 1) END AS ctr, CASE WHEN COUNT(CASE WHEN b.behavior_type = 1 THEN 1 END) = 0 THEN 0 ELSE ROUND(100 * COUNT(CASE WHEN b.behavior_type = 1 AND b.source = 4 THEN 1 END) / COUNT(CASE WHEN b.behavior_type = 1 THEN 1 END), 1) END AS click_share FROM ai_user_behavior b WHERE b.create_time >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
